// Creo Explorer Property Handler - column mapping
//
// Place this file next to CreoExplorerHandler.dll (same folder).
// Edit mappings, then re-run Register.ps1 when you ADD a new left-side name.
// Changing only the Creo parameter on an existing left-side name: F5 / restart Explorer.
//
// Format (one mapping per line):
//   "Windows property or header" "CREO_PARAMETER_NAME"
//
// Lines that start with // are comments. Blank lines are ignored.
//
// Left side: Explorer header alias OR a real Windows canonical name (System.*).
// Right side: exact Creo USER parameter name (usually UPPERCASE). String type only.
//
// IMPORTANT: Many short names like System.Initials are NOT valid. Use the
// corrected names below. Invalid System.* names are ignored (value will not appear).
//
// Default mappings:

"System.Document.RevisionNumber" "SYS_REVISION"
"System.FileVersion" "SYS_FILEVERSION"
"System.Document.Version" "SYS_FILEVERSION"
"System.ContentStatus" "SYS_STATUS"
"System.Author" "SYS_AUTHORS"
"System.Contact.Initials" "SYS_APPROVED_BY_INITIALS"
"System.Title" "SYS_TITLE"
"System.Media.SubTitle" "SYS_SUBTITLE"
"System.Company" "SYS_COMPANY"
"System.Contact.Department" "SYS_DEPARTMENT"
"System.ApplicationName" "SYS_PROGRAM_NAME"
"System.Project" "SYS_PROJECT"
"System.Category" "SYS_CATEGORY"
"System.SensitivityText" "SYS_CLASSIFICATION"
"System.Photo.CameraManufacturer" "SYS_MANUFACTURER"
"System.Contact.OfficeLocation" "SYS_LOCATION"
"System.Keywords" "SYS_TAGS"
"System.Comment" "SYS_COMMENTS"
"System.Subject" "SYS_SUBJECT"

// Corrections for common mistaken names (also handled as aliases in the DLL):
//   System.ProductVersion  -> does not exist; use System.Document.RevisionNumber
//   System.Initials        -> System.Contact.Initials
//   System.Subtitle        -> System.Media.SubTitle   (capital T in SubTitle)
//   System.Department      -> System.Contact.Department
//   System.ProgramName     -> System.ApplicationName
//   System.Classification  -> System.SensitivityText
//   System.Manufacturer    -> System.Photo.CameraManufacturer
//   System.Location        -> System.Contact.OfficeLocation
//
// Note: System.Document.RevisionNumber / System.Document.Version show in
// Properties > Details but often have NO Explorer Details-view column.
